import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>

// Min reduction over dim=1 of a [B, D1, D2] contiguous float tensor.
// Each thread computes one output element out[b, d] = min_i x[b, i, d].
// Consecutive threads map to consecutive d, so all global loads are
// perfectly coalesced even though the reduction stride is D2.
__global__ void min_reduce_dim1_kernel(const float* __restrict__ x,
                                       float* __restrict__ out,
                                       int dim1, int dim2,
                                       long long total) {
    // Warp-coarsened reduction: each warp handles 128 consecutive output
    // elements (4 per lane, strided by 32 so every load instruction is
    // still fully coalesced across the warp). Each lane keeps 4
    // independent accumulator chains and the dim1 loop is unrolled by 2,
    // giving up to 8 outstanding global loads per thread to hide memory
    // latency and saturate bandwidth on this memory-bound reduction.
    const int lane = threadIdx.x & 31;
    const long long numWarps = ((long long)gridDim.x * blockDim.x) >> 5;
    const long long numChunks = (total + 127) >> 7;
    const float inf = __int_as_float(0x7f800000);
    for (long long w = ((long long)blockIdx.x * blockDim.x + threadIdx.x) >> 5;
         w < numChunks; w += numWarps) {
        long long o0 = (w << 7) + lane;
        const float* p[4];
        long long o[4];
        float m[4];
        #pragma unroll
        for (int k = 0; k < 4; ++k) {
            o[k] = o0 + 32 * k;
            long long oo = (o[k] < total) ? o[k] : 0;
            int b = (int)(oo / dim2);
            int d = (int)(oo - (long long)b * dim2);
            p[k] = x + (long long)b * dim1 * dim2 + d;
            m[k] = inf;
        }
        int i = 0;
        for (; i + 1 < dim1; i += 2) {
            #pragma unroll
            for (int k = 0; k < 4; ++k) {
                float v0 = __ldg(p[k]);
                float v1 = __ldg(p[k] + dim2);
                m[k] = fminf(m[k], fminf(v0, v1));
                p[k] += 2 * (long long)dim2;
            }
        }
        if (i < dim1) {
            #pragma unroll
            for (int k = 0; k < 4; ++k) {
                m[k] = fminf(m[k], __ldg(p[k]));
            }
        }
        #pragma unroll
        for (int k = 0; k < 4; ++k) {
            if (o[k] < total) out[o[k]] = m[k];
        }
    }
}

torch::Tensor min_reduce_dim1(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(x.dim() == 3, "input must be 3D");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "input must be float32");

    auto xc = x.contiguous();
    int64_t batch = xc.size(0);
    int64_t dim1  = xc.size(1);
    int64_t dim2  = xc.size(2);

    auto out = torch::empty({batch, dim2}, xc.options());
    long long total = (long long)batch * dim2;
    if (total == 0) return out;

    int threads = 256;
    long long blocks = (total + (long long)threads * 4 - 1) / ((long long)threads * 4);
    if (blocks > 65535) blocks = 65535;

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    min_reduce_dim1_kernel<<<(int)blocks, threads, 0, stream>>>(
        xc.data_ptr<float>(), out.data_ptr<float>(),
        (int)dim1, (int)dim2, total);
    return out;
}
"""

_cpp_src = "torch::Tensor min_reduce_dim1(torch::Tensor x);"

_mod = load_inline(
    name="min_reduce_dim1_ext",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["min_reduce_dim1"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Model that performs min reduction over a specific dimension,
    using a custom CUDA kernel for the dim == 1 case.
    """
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if (self.dim == 1 and x.is_cuda and x.dim() == 3
                and x.dtype == torch.float32):
            return _mod.min_reduce_dim1(x)
        return torch.min(x, dim=self.dim)[0]

